select 
from config_item
where id = #{id}
  and tenant_id = #{tenantId}
  and deleted = 0

select 
from config_item
where tenant_id = #{tenantId}
  and config_type = #{configType}
  and config_code = #{configCode}
  and deleted = 0
order by version_no desc
limit 1

select 
from config_item
where tenant_id = #{tenantId}
  and config_type = #{configType}
  and deleted = 0

  and (config_code like concat('%', #{keyword}, '%') or config_name like concat('%', #{keyword}, '%'))


  and status = #{status}


  and biz_scene = #{bizScene}

order by updated_at desc, id desc
limit #{limit} offset #{offset}

select count(1)
from config_item
where tenant_id = #{tenantId}
  and config_type = #{configType}
  and deleted = 0

  and (config_code like concat('%', #{keyword}, '%') or config_name like concat('%', #{keyword}, '%'))


  and status = #{status}


  and biz_scene = #{bizScene}

select 
from config_item
where tenant_id = #{tenantId}
  and config_type = 'RULE_DEFINITION'
  and status = 'PUBLISHED'
  and deleted = 0

  and biz_scene = #{scene}


  and config_code = #{ruleCode}

order by config_code asc, version_no desc

mapper.update:
update config_item
set status = #{status},
    updated_at = now()
where id = #{id}
  and tenant_id = #{tenantId}
  and deleted = 0

update config_item
set deleted = 1,
    updated_at = now()
where id = #{id}
  and tenant_id = #{tenantId}
  and deleted = 0
